export class SpatialGridHelper {
    /**
     * Create a spatial grid visualization helper.
     *
     * @param {Physics} physics - The Physics instance.
     * @param {Object} [options] - Configuration options.
     * @param {number} [options.cellSize=4] - Size of each grid cell in world units.
     * @param {number} [options.gridExtent=6] - Number of cells to show in each direction from center.
     * @param {boolean} [options.showQueryRadius=true] - Highlight the query radius area.
     * @param {number} [options.queryRadius=3] - Radius used for spatial queries (capsule size).
     * @param {number} [options.gridColor=0x888888] - Color of grid lines (grey).
     * @param {number} [options.queryColor=0x00ff88] - Color of query radius box (yellow).
     * @param {number} [options.activeColor=0xffff00] - Color of active cells (green).
     * @param {THREE.Object3D} [options.target] - Target object to follow (uses interpolated position).
     * @param {boolean} [options.enabled=true] - Whether to start enabled.
     */
    constructor(physics: Physics, options?: {
        cellSize?: number;
        gridExtent?: number;
        showQueryRadius?: boolean;
        queryRadius?: number;
        gridColor?: number;
        queryColor?: number;
        activeColor?: number;
        target?: THREE.Object3D;
        enabled?: boolean;
    });
    physics: Physics;
    cellSize: number;
    gridExtent: number;
    showQueryRadius: boolean;
    queryRadius: number;
    gridColor: number;
    queryColor: number;
    activeColor: number;
    target: any;
    enabled: boolean;
    visible: boolean;
    _gridLines: any;
    _queryBox: any;
    _activeCells: any;
    _centerCell: any;
    _lastCenterCell: any;
    _lastPlayerPos: any;
    _tempWorldPos: any;
    _cellGeometry: BoxNoFaceGeometry;
    _cellMaterial: any;
    /**
     * Set the cell size (should match PhysicsSpatialGrid.cellSize).
     * @param {number} size - Cell size in world units.
     */
    setCellSize(size: number): void;
    /**
     * Set the grid extent (number of cells from center).
     * @param {number} extent - Number of cells in each direction.
     */
    setGridExtent(extent: number): void;
    /**
     * Set the query radius for visualization.
     * @param {number} radius - Query radius in world units.
     */
    setQueryRadius(radius: number): void;
    /**
     * Set the target object to follow (uses interpolated position).
     * @param {THREE.Object3D} target - Target object (e.g., player mesh).
     */
    setTarget(target: THREE.Object3D): void;
    /**
     * Enable or disable the helper.
     * @param {boolean} enabled - Whether to show the visualization.
     */
    setEnabled(enabled: boolean): void;
    /**
     * Toggle enabled state.
     */
    toggle(): void;
    /**
     * Update the visualization. Call every frame.
     * Positions the grid around the player and updates the query radius box.
     */
    update(): void;
    /**
     * Rebuild the grid visualization.
     * @private
     */
    private _rebuildGrid;
    /**
     * Create the grid line visualization.
     * @private
     */
    private _createGrid;
    /**
     * Create the query radius box visualization.
     * @private
     */
    private _createQueryBox;
    /**
     * Update the query box size based on query radius.
     * @private
     */
    private _updateQueryBox;
    /**
     * Create the active cells container.
     * @private
     */
    private _createActiveCells;
    /**
     * Update the active cells visualization based on player position.
     * @param {number} px - Player world X position.
     * @param {number} py - Player world Y position.
     * @param {number} pz - Player world Z position.
     * @private
     */
    private _updateActiveCells;
    /**
     * Dispose of the helper and free resources.
     */
    dispose(): void;
}
import { BoxNoFaceGeometry } from '@three-blocks/core';
